import json
G=[[0]*30 for _ in range(30)]
mat=[[3,2,2,3],[2,8,8,2],[3,2,2,3],[2,8,8,2]]
starts=[1,8,15,22,29]
for ti,r0 in enumerate(starts):
 for tj,c0 in enumerate(starts):
  for dr in range(min(5,30-r0)):
   for dc in range(min(5,30-c0)):
    G[r0+dr][c0+dc]=4
for ti,r0 in enumerate(starts[:4]):
 for tj,c0 in enumerate(starts[:4]):
  for dr in range(1,4):
   for dc in range(1,4): G[r0+dr][c0+dc]=mat[ti][tj]
# connectors, later-seen color overwrites earlier along each line
# calculate horizontal gaps per row of tiles
for ti,r0 in enumerate(starts[:4]):
 vals=mat[ti]
 for colr in sorted(set(vals), key=lambda v: vals.index(v)):
  inds=[j for j,v in enumerate(vals) if v==colr]
  if len(inds)==2:
   for j in range(min(inds),max(inds)):
    for dr in range(1,4):
     for dc in (5,6): G[r0+dr][starts[j]+dc]=colr
# vertical
for tj,c0 in enumerate(starts[:4]):
 vals=[mat[i][tj] for i in range(4)]
 for colr in sorted(set(vals), key=lambda v: vals.index(v)):
  inds=[i for i,v in enumerate(vals) if v==colr]
  if len(inds)==2:
   for i in range(min(inds),max(inds)):
    for dc in range(1,4):
     for dr in (5,6): G[starts[i]+dr][c0+dc]=colr
print(json.dumps(G,separators=(',',':')))

